      clave: [['Velocidad de corte', 'Velocidad del filo respecto al material, en m/min'], ['rpm', 'Revoluciones por minuto del husillo'], ['Avance', 'Distancia que avanza la herramienta por vuelta o por minuto'], ['Avance por diente (fz)', 'Material que corta cada filo de la fresa en cada vuelta'], ['HSS', 'Acero rápido: material común de brocas y fresas']],
