      pantalla: ['Bloque: N · G · X Y Z · I J · F · S · T · M', 'G00 rápido · G01 lineal · G02 arco horario · G03 antihorario', 'G21 mm · G90 absolutas · G91 incrementales · G54 cero pieza', 'M03 husillo · M05 paro · M06 herramienta · M08 refrigerante · M30 fin', 'Láser GRBL: M3/M4 con S = potencia', 'Modales: se quedan activos hasta cambiarlos'],
      clave: [['Bloque', 'Renglón de un programa CNC'], ['Código G', 'Función preparatoria: indica el tipo de movimiento o modo'], ['Código M', 'Función auxiliar: husillo, refrigerante, fin de programa'], ['Modal', 'Código que sigue activo en los bloques siguientes'], ['F', 'Avance de corte, en mm/min en modo G94']],
      ejemplo: { titulo: 'Leer un programa corto', pasos: ['G21 G90 G17 → milímetros, absolutas, plano XY.', 'G00 Z5 → sube rápido a 5 mm sobre la pieza.', 'G00 X10 Y10 → va rápido a la esquina de inicio.', 'M03 S2000 → husillo horario a 2000 rpm.', 'G01 Z-1 F100 → entra 1 mm; G01 X50 F300 → corta hasta X50.', 'G00 Z5 → sale; M05 → paro; M30 → fin.'], resultado: 'Leído bloque por bloque, el programa cuenta una historia: acercarse, cortar y salir.' },
      preguntas: [['¿Qué diferencia hay entre G00 y G01?', 'G00 es movimiento rápido sin cortar; G01 es lineal cortando con avance F.'], ['¿Qué hace M30?', 'Termina el programa y regresa al inicio.'], ['¿Qué significa que un código sea modal?', 'Que sigue activo en los bloques siguientes hasta que otro lo cambie.'], ['¿Con qué código se elige trabajar en milímetros?', 'G21.']],
      errores: ['Usar G00 dentro del material: choca la herramienta.', 'Olvidar F en el primer G01.', 'Confundir G02 y G03.', 'Olvidar encender el husillo antes de cortar.'],
