    { id: 'm4-lista-arranque', titulo: 'Lista de arranque de la máquina', sm: ['IV-1'], tipo: 'Docencia', dur: '15 min', costo: '$0', obj: 'Que el arranque seguro sea un hábito y no un recuerdo.', mat: ['Lista impresa y enmicada junto a cada máquina'],
      pasos: ['Escriban con el grupo los puntos de arranque de cada máquina.', 'Enmiquen y péguenla junto a la máquina.', 'Antes de cada uso, un compañero la lee y otro la ejecuta.', 'El docente firma la primera vez de cada alumno.'], evid: 'Lista firmada', tip: 'Que la lista la escriban ellos: la respetan más que una que les entregas.' },
    { id: 'm4-cnc-por-dentro', titulo: 'La CNC por dentro', sm: ['IV-1'], tipo: 'Práctica', dur: '30 min', costo: 'Bajo', obj: 'Reconocer motores, guías, bandas o husillos, interruptores de límite y control.', mat: ['Impresora o escáner viejo donado, desconectado', 'Desarmadores', 'La cortadora láser apagada con la tapa abierta'],
      pasos: ['Desarmen la impresora (desconectada) y busquen motores, guías, bandas y sensores.', 'Comparen con la cortadora láser apagada.', 'Dibujen el diagrama de bloques: control, drivers, motores, transmisión y referencia.', 'Guarden motores y guías para proyectos.'], evid: 'Diagrama de bloques', tip: 'Las impresoras viejas traen motores, guías y hasta tiras de encoder: son material de robótica gratis.' },
    { id: 'm4-maquina-humana', titulo: 'Máquina humana', sm: ['IV-1'], tipo: 'Dinámica', dur: '30 min', costo: '$0', obj: 'Entender que la máquina hace exactamente lo que dice el código, ni más ni menos.', mat: ['Papel milimétrico grande o pizarrón con ejes', 'Plumón'],
      pasos: ['Un equipo escribe un programa con G00, G01 y un arco.', 'Un alumno de otro equipo lo ejecuta: G00 con el plumón levantado, G01 apoyado.', 'No puede preguntar ni corregir: hace lo que dice el bloque.', 'Comparan la figura con la intención y corrigen.'], evid: 'Programa corregido y figura', tip: 'Elige como «máquina» al alumno más literal del grupo: los errores de código salen solos.' },
    { id: 'm4-batalla-coordenadas', titulo: 'Batalla de coordenadas', sm: ['IV-1'], tipo: 'Dinámica', dur: '20 min', costo: '$0', obj: 'Practicar coordenadas absolutas e incrementales jugando.', mat: ['Hojas cuadriculadas con ejes de 0 a 60'],
      pasos: ['En parejas, cada quien esconde 4 piezas en su cuadrícula.', 'Ronda 1: disparan en absolutas (X40 Y20).', 'Ronda 2: disparan en incrementales desde el último disparo (X-10 Y5).', 'Gana quien hunda primero; revisen los disparos mal calculados.'], evid: 'Hoja de disparos', tip: 'En la ronda incremental se nota quién entendió: los errores de signo aparecen de inmediato.' },
    { id: 'm4-codigo-roto', titulo: 'Código G roto: encuentra los errores', sm: ['IV-1'], tipo: 'Dinámica', dur: '20 min', costo: '$0', obj: 'Practicar la revisión de programas antes de simular.', mat: ['Programa impreso con 5 errores (G00 dentro del material, falta F, arco al revés, sin M05, Z de más)'],
      pasos: ['Reparte el programa en parejas.', 'Marcan los errores sin computadora.', 'Los clasifican: choque, pieza mal hecha o máquina en mal estado.', 'Comprueban en el simulador.'], evid: 'Programa marcado', tip: 'Incluye un error que el simulador no marca como choque (un arco al revés que sí cabe): enseña a mirar la forma, no solo los choques.' },
    { id: 'm4-placa-barrenos', titulo: 'Patrón de barrenos con incrementales', sm: ['IV-1'], tipo: 'Práctica', dur: '20 min', costo: '$0', obj: 'Usar incrementales y ciclos para repetir operaciones.', mat: ['Plano de una placa con 4 × 3 barrenos', 'Simulador'],
      pasos: ['Programen el primer barreno en absolutas.', 'Los demás en incrementales con el mismo paso.', 'Compárenlo con el programa en absolutas: ¿cuál es más corto?', 'Simulen ambos.'], evid: 'Dos programas y su simulación', tip: 'Cambia el paso entre barrenos y pregunta cuántos bloques hay que corregir en cada versión.' },
    { id: 'm4-kerf', titulo: 'Peine de prueba para medir el kerf', sm: ['IV-1'], tipo: 'Práctica', dur: '15 min', costo: 'Bajo', obj: 'Medir el ancho de corte real del láser en el material que se va a usar.', mat: ['Archivo con 10 cuadros de 10 mm en fila', 'Placa de MDF', 'Vernier'],
      pasos: ['Corta los 10 cuadros sin compensar.', 'Júntalos en fila y mide el largo total.', 'kerf ≈ (100 − largo medido) / 10.', 'Usa ese valor para compensar las piezas.'], evid: 'Valor de kerf medido', tip: 'Repite con acrílico: cada material y cada potencia dan un kerf distinto.' },
    { id: 'm4-pasa-no-pasa', titulo: 'Calibrador pasa/no pasa en MDF', sm: ['IV-1'], tipo: 'Práctica', dur: '30 min', costo: 'Bajo', obj: 'Revisar rápido muchas piezas contra sus límites.', mat: ['Archivo con dos ranuras: límite menor y límite mayor', 'Placa de MDF', 'Vernier'],
      pasos: ['Diseñen el calibrador para el espesor de los eslabones o la ranura del servo.', 'Córtenlo y mídanlo: el calibrador también se verifica.', 'Revisen todas las piezas: debe pasar por el lado «pasa» y no por el «no pasa».', 'Comparen con la medición con vernier.'], evid: 'Calibrador y lista de piezas revisadas', tip: 'Así revisan los inspectores en producción: en segundos y sin interpretar números.' },
    { id: 'm4-visita-virtual', titulo: 'Visita a un taller de maquinado (real o virtual)', sm: ['IV-1'], tipo: 'Formación', dur: '2 h', costo: '$0', obj: 'Ver máquinas reales en producción y hablar con quien las opera.', mat: ['Permiso de la escuela y de la empresa', 'Guía de observación'],
      pasos: ['Busquen un taller de troqueles, moldes o maquinado de la región (el calzado de León y San Francisco usa muchos).', 'Preparen 5 preguntas sobre su trabajo y su formación.', 'Durante la visita identifican máquinas, operaciones y medidas de seguridad.', 'Si no hay visita, usen videos de recorridos y una videollamada con un egresado.'], evid: 'Guía de observación', tip: 'Pide fotos solo de máquinas y piezas, nunca de rostros, y respeta lo que la empresa no permita mostrar.' }
